/* Maps content records to image slots in the generated manifest.
 * Kept separate from universities.ts / countries.ts so the fee data
 * stays purely factual, and separate from images.ts because that file
 * is regenerated by `npm run images`.
 *
 * IMAGE COVERAGE. The client's photo manifest covers five of the
 * nineteen universities. The rest have no photography of their own,
 * so they resolve to country-level imagery and are captioned by
 * COUNTRY, never by a city or campus we have no picture of. Getting
 * this wrong would put a stock photo of one place under the name of
 * another on a page where families commit lakhs.
 *
 * Kazan State Medical University and Chitwan Medical College were
 * added without campus photography — both fall back to country
 * imagery with country captions until the client supplies photos.
 */

/** Universities the client's photo manifest actually covers. */
export const MANIFEST_SLUGS = new Set([
  "geomedi-university-georgia",
  "kemerovo-state-medical-university",
  "north-caucasian-state-academy",
  "ingush-state-university",
  "university-of-south-asia-kyrgyzstan",
]);

export function hasManifest(slug: string): boolean {
  return MANIFEST_SLUGS.has(slug);
}

