  "east-west-university-georgia": "Old town Tbilisi, Georgia",
  "david-tvildiani-medical-university": "Tbilisi, Georgia",

  "north-caucasian-state-academy": "North Caucasus, Russia",
  "ingush-state-university": "Magas, Ingushetia, Russia",
  "kemerovo-state-medical-university": "Kemerovo region, Russia",
  "kazan-state-medical-university": "Russia",

  "kazakh-national-medical-university": "Kazakhstan",
