export function uniImage(slug: string): string {
  return UNI_IMAGE[slug] ?? "students-campus";
}

export function uniCaption(slug: string): string {
  return UNI_IMAGE_CAPTION[slug] ?? "";
}

/** Wide photograph for the page hero. Universities in the manifest use
 *  their own city skyline; the rest fall back to the country image. */
export function uniHero(slug: string): string {
  if (slug === "geomedi-university-georgia") return "uni-geomedi";
  if (hasManifest(slug)) return `uni:${slug}:City/01_Skyline`;
  return uniImage(slug);
}

const UNI_HERO_CAPTION: Record<string, string> = {
  "geomedi-university-georgia": "Tbilisi, Georgia",
};

export function uniHeroCaption(slug: string): string {
  return UNI_HERO_CAPTION[slug] ?? UNI_IMAGE_CAPTION[slug] ?? "";
}

/* ------------------------------------------------------------------
   Inline photography on a university page.

   Manifest universities use their own city and teaching shots. The
   rest use generic medical-education imagery, which the captions
   already describe generically ("Clinical rotations from year three",
   "Laboratories and practical work") rather than claiming to show
   that campus.
   ------------------------------------------------------------------ */
type UniSlot = "city" | "hospital" | "laboratory" | "students";

const SLOT_MANIFEST_KEY: Record<UniSlot, string> = {
  city: "City/03_City_Centre",
  hospital: "University/04_Hospital_Clinical",
  laboratory: "University/02_Laboratory",
  students: "University/05_Students_Indian_Students",
};

const SLOT_FALLBACK: Record<UniSlot, string> = {
  city: "students-campus",
  hospital: "hospital-ward",
  laboratory: "laboratory",
  students: "students-friends",
};

export function uniSlotImage(slug: string, slot: UniSlot): string {
  return hasManifest(slug) ? `uni:${slug}:${SLOT_MANIFEST_KEY[slot]}` : SLOT_FALLBACK[slot];
}

/** Caption for the inline city image. Only names a city where we
 *  actually hold a photograph of it. */
export function uniCityCaption(slug: string): string {
  return hasManifest(slug) ? uniCaption(slug) : "";
}

export function countryImage(slug: string): string {
  return `country-${slug}`;
}

export function countryImageAlt(slug: string): string {
  return `country-${slug}-alt`;
}

