/* ------------------------------------------------------------------
   Destination pages prefer the client manifest's City/* photographs,
   which are genuine shots of the cities we actually place students
   into. Countries with no manifest coverage (China, Kazakhstan) fall
   back to the country gallery above.
   ------------------------------------------------------------------ */
const COUNTRY_CITY_SOURCES: Record<string, { slug: string; label: string }[]> = {
  georgia: [{ slug: "geomedi-university-georgia", label: "Tbilisi" }],
  russia: [
    { slug: "north-caucasian-state-academy", label: "Cherkessk" },
    { slug: "ingush-state-university", label: "Magas" },
    { slug: "kemerovo-state-medical-university", label: "Kemerovo" },
  ],
  kyrgyzstan: [{ slug: "university-of-south-asia-kyrgyzstan", label: "Bishkek" }],
};

const CITY_SLOT_LABEL: Record<string, string> = {
  "City/01_Skyline": "Skyline",
  "City/02_Landmark": "Landmark",
  "City/03_City_Centre": "City centre",
  "City/04_City_Life": "Everyday life",
};

/** Returns `uni:` image ids plus captions for a country's cities.
 *  One country with three universities (Russia) shows one slot from
 *  each city first, so the gallery reads as a tour of the country
 *  rather than four angles on one town. */
export function countryCityTiles(countrySlug: string): GalleryTile[] {
  const sources = COUNTRY_CITY_SOURCES[countrySlug];
  if (!sources) return [];

  const slots = Object.keys(CITY_SLOT_LABEL);
  const tiles: GalleryTile[] = [];

  if (sources.length === 1) {
    const { slug, label } = sources[0];
    slots.forEach((key) => {
      tiles.push({
        id: `uni:${slug}:${key}`,
        caption: `${label} — ${CITY_SLOT_LABEL[key]}`,
      });
    });
  } else {
    // Round-robin across cities, one slot each, then wrap.
    for (let i = 0; i < slots.length; i++) {
      const src = sources[i % sources.length];
      tiles.push({
        id: `uni:${src.slug}:${slots[i]}`,
        caption: `${src.label} — ${CITY_SLOT_LABEL[slots[i]]}`,
      });
    }
  }

  // Bento emphasis on the first and last tiles.
  if (tiles[0]) tiles[0].span = "col-span-2 row-span-2";
  if (tiles[3]) tiles[3].span = "col-span-2";
  return tiles;
}

